import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.il0noOp3.js";const p=JSON.parse('{"title":"App and Data Modernization — enumerated source for the App and Data Modernization Readiness Tool","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/app-modernization-question-set.md","filePath":"frameworks/app-modernization-question-set.md"}'),n={name:"frameworks/app-modernization-question-set.md"};function s(o,t,i,c,l,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="app-and-data-modernization-—-enumerated-source-for-the-app-and-data-modernization-readiness-tool" tabindex="-1">App and Data Modernization — enumerated source for the App and Data Modernization Readiness Tool <a class="header-anchor" href="#app-and-data-modernization-—-enumerated-source-for-the-app-and-data-modernization-readiness-tool" aria-label="Permalink to &quot;App and Data Modernization — enumerated source for the App and Data Modernization Readiness Tool&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>appmod.readiness.yaml</code> scores the readiness factors behind Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/assessments/50adbf76-60fb-47ce-a787-f9d5f52f6a48/" target="_blank" rel="noreferrer">App and Data Modernization Readiness Tool</a>. The guidance says an organization is only as ready as its people, infrastructure, development processes, data management, application estate and operations. This page lists the items Scout asks, and every rule in that file cites an item number from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/50adbf76-60fb-47ce-a787-f9d5f52f6a48/" target="_blank" rel="noreferrer">App and Data Modernization Readiness Tool</a> (30 minutes, multiple choice and multiple response; question text not published)</td></tr><tr><td>Framework version</td><td>Microsoft Azure App Modernization Guidance on Microsoft Learn, current at the extraction date. Not versioned by Microsoft</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>The assessment landing page and the guidance home, &quot;Are you ready for application and data modernization?&quot;, maturity model, &quot;Make an inventory and collect data&quot;, &quot;Identity, security, and compliance best practices&quot; and &quot;The 6 Rs&quot; pages were fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25. Every <code>collect.json</code> property an automated item reads was checked against the header contract in <code>src/collect/Invoke-Collect.ps1</code>.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list.</strong> The assessment&#39;s questions are not published. The items below are <strong>Scout&#39;s</strong> reading of the readiness guidance, mainly the &quot;Are you ready for application and data modernization?&quot; page, whose sections (organizational maturity, infrastructure, process, data management, application estate, AI adoption and operations) set the areas used here. The <code>APPMOD-*</code> IDs are Scout&#39;s.</p><p>The guidance also describes four maturity categories (traditional foundations, emerging pioneers, agile innovators, digital champions). Scout asks whether the organization knows which it is in but does not assign one, because the category depends on business readiness that Azure data cannot show. The score is the share of items met.</p><p>Sources:</p><ul><li>[READY] <a href="https://learn.microsoft.com/azure/app-modernization-guidance/assess/are-you-ready-for-application-and-data-modernization" target="_blank" rel="noreferrer">Are you ready for application and data modernization?</a></li><li>[MAT] <a href="https://learn.microsoft.com/azure/app-modernization-guidance/get-started/application-modernization-maturity-model" target="_blank" rel="noreferrer">Application modernization maturity model</a></li><li>[INVN] <a href="https://learn.microsoft.com/azure/app-modernization-guidance/assess/make-an-inventory-and-collect-data" target="_blank" rel="noreferrer">Make an inventory and collect data</a></li><li>[PLAN6] <a href="https://learn.microsoft.com/azure/app-modernization-guidance/plan/the-6-rs-of-application-modernization" target="_blank" rel="noreferrer">The 6 Rs of application modernization</a></li><li>[LAUNCH] <a href="https://learn.microsoft.com/azure/app-modernization-guidance/launch/identity-security-and-compliance-best-practices" target="_blank" rel="noreferrer">Identity, security, and compliance best practices</a></li></ul><h2 id="how-the-items-are-answered" tabindex="-1">How the items are answered <a class="header-anchor" href="#how-the-items-are-answered" aria-label="Permalink to &quot;How the items are answered&quot;">​</a></h2><p>Most items are questions about how the organization works, which no Azure API can read. They are <strong>manual</strong> rules: Scout lists them in <code>assessment-questions.csv</code> (or <code>Export-ScoutAssessmentQuestion</code>), and a person answers <code>Yes</code>, <code>Partial</code>, <code>No</code> or <code>N/A</code>. See <a href="./../assessment/questionnaire-answers.html">Questionnaire answers</a>. Where collected Azure data bears on a question, it is attached to the item as evidence, but the answer still decides the score. Items marked ✅ are <strong>automated</strong> and <strong>gated</strong>: they run only when the resources they read exist (or the data source was collected), so an estate without them reports the item Not assessed, never Passed or Failed, and an answer file cannot override them.</p><h2 id="the-enumeration-—-62-items-across-9-areas" tabindex="-1">The enumeration — 62 items across 9 areas <a class="header-anchor" href="#the-enumeration-—-62-items-across-9-areas" aria-label="Permalink to &quot;The enumeration — 62 items across 9 areas&quot;">​</a></h2><h3 id="organizational-maturity-and-skills-appmod-org-—-4-items" tabindex="-1">Organizational maturity and skills (APPMOD-ORG) — 4 items <a class="header-anchor" href="#organizational-maturity-and-skills-appmod-org-—-4-items" aria-label="Permalink to &quot;Organizational maturity and skills (APPMOD-ORG) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>APPMOD-ORG-01</td><td>Developer teams&#39; maturity in tools, culture and processes has been assessed, for example with the Developer Velocity Index, and the gaps are tracked</td><td>❌ Manual</td><td>READY</td></tr><tr><td>APPMOD-ORG-02</td><td>The organization knows which application modernization maturity category it is in (traditional foundations, emerging pioneers, agile innovators, digital champions) and plans work to match</td><td>❌ Manual</td><td>MAT</td></tr><tr><td>APPMOD-ORG-03</td><td>Stakeholders are aligned on modernization goals, scope and the order of work</td><td>❌ Manual</td><td>MAT, READY</td></tr><tr><td>APPMOD-ORG-04</td><td>Team skills are assessed regularly, and training closes the gaps in modern tools and platforms</td><td>❌ Manual</td><td>READY</td></tr></tbody></table><h3 id="estate-inventory-and-assessment-appmod-inv-—-7-items" tabindex="-1">Estate inventory and assessment (APPMOD-INV) — 7 items <a class="header-anchor" href="#estate-inventory-and-assessment-appmod-inv-—-7-items" aria-label="Permalink to &quot;Estate inventory and assessment (APPMOD-INV) — 7 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>APPMOD-INV-01</td><td>A complete inventory lists every application, database and infrastructure component, on-premises and in the cloud, with its purpose, usage and dependencies</td><td>❌ Manual — Azure virtual machines attached</td><td>INVN</td></tr><tr><td>APPMOD-INV-02</td><td>Dependencies among applications, databases and services are mapped</td><td>❌ Manual</td><td>INVN</td></tr><tr><td>APPMOD-INV-03</td><td>Application binaries and source code are assessed for cloud readiness, for example with Azure Migrate application and code assessment (AppCAT)</td><td>❌ Manual</td><td>INVN</td></tr><tr><td>APPMOD-INV-04</td><td>Data is classified by sensitivity, compliance requirements and business value</td><td>❌ Manual</td><td>INVN</td></tr><tr><td>APPMOD-INV-05</td><td>A security baseline exists, such as the Defender for Cloud secure score, with prioritized recommendations</td><td>❌ Manual — Defender for Cloud secure scores attached</td><td>INVN</td></tr><tr><td>APPMOD-INV-06</td><td>Regulatory and compliance requirements are identified before modernization plans are made, with evidence of compliance activities kept</td><td>❌ Manual</td><td>INVN</td></tr><tr><td>APPMOD-INV-07</td><td>A cost baseline exists (total cost of ownership) for current environments, with savings opportunities identified</td><td>❌ Manual</td><td>INVN</td></tr></tbody></table><h3 id="infrastructure-and-network-readiness-appmod-inf-—-8-items" tabindex="-1">Infrastructure and network readiness (APPMOD-INF) — 8 items <a class="header-anchor" href="#infrastructure-and-network-readiness-appmod-inf-—-8-items" aria-label="Permalink to &quot;Infrastructure and network readiness (APPMOD-INF) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>APPMOD-INF-01</td><td>Current hardware and software can support modern applications and AI workloads</td><td>❌ Manual</td><td>READY</td></tr><tr><td>APPMOD-INF-02</td><td>Infrastructure can scale to meet future demand</td><td>❌ Manual — Azure Monitor autoscale settings attached</td><td>READY</td></tr><tr><td>APPMOD-INF-03</td><td>Network bandwidth and latency can handle the traffic and latency needs of modern applications</td><td>❌ Manual — ExpressRoute circuits attached</td><td>READY</td></tr><tr><td>APPMOD-INF-04</td><td>Redundant network paths provide high availability</td><td>❌ Manual — VPN connections attached</td><td>READY</td></tr><tr><td>APPMOD-INF-05</td><td>Network security measures protect applications and data</td><td>❌ Manual — Azure Firewall policies attached</td><td>READY</td></tr><tr><td>APPMOD-INF-06</td><td>The organization is ready for a hybrid cloud setup, with some resources on-premises and some in the cloud</td><td>❌ Manual — Azure Arc-enabled servers attached</td><td>READY</td></tr><tr><td>APPMOD-INF-07</td><td>Infrastructure is deployed through automation (infrastructure as code) instead of manual changes</td><td>✅ deployment records with a template hash</td><td>READY</td></tr><tr><td>APPMOD-INF-08</td><td>Monitoring tools track the performance, availability and security of infrastructure, and no resource type is left without diagnostics</td><td>✅ diagnostic coverage by resource type</td><td>READY</td></tr></tbody></table><h3 id="process-readiness-appmod-prc-—-7-items" tabindex="-1">Process readiness (APPMOD-PRC) — 7 items <a class="header-anchor" href="#process-readiness-appmod-prc-—-7-items" aria-label="Permalink to &quot;Process readiness (APPMOD-PRC) — 7 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>APPMOD-PRC-01</td><td>Source code is held in version-controlled repositories</td><td>✅ Azure DevOps Git repositories (needs -IncludeDevOps)</td><td>READY</td></tr><tr><td>APPMOD-PRC-02</td><td>A branching strategy, frequent commits and pull requests are standard practice</td><td>❌ Manual</td><td>READY</td></tr><tr><td>APPMOD-PRC-03</td><td>A code review process checks quality, consistency and adherence to best practice</td><td>❌ Manual</td><td>READY</td></tr><tr><td>APPMOD-PRC-04</td><td>Semantic versioning and a change log are maintained</td><td>❌ Manual</td><td>READY</td></tr><tr><td>APPMOD-PRC-05</td><td>Builds and deployments run through automated CI/CD pipelines</td><td>✅ Azure DevOps pipelines (needs -IncludeDevOps)</td><td>READY</td></tr><tr><td>APPMOD-PRC-06</td><td>Automated unit, integration and end-to-end tests run in the pipeline</td><td>❌ Manual — Azure Playwright Testing resources attached</td><td>READY</td></tr><tr><td>APPMOD-PRC-07</td><td>Monitoring and alerting track application performance and health after deployment</td><td>❌ Manual — Application Insights components attached</td><td>READY</td></tr></tbody></table><h3 id="data-readiness-appmod-dat-—-9-items" tabindex="-1">Data readiness (APPMOD-DAT) — 9 items <a class="header-anchor" href="#data-readiness-appmod-dat-—-9-items" aria-label="Permalink to &quot;Data readiness (APPMOD-DAT) — 9 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>APPMOD-DAT-01</td><td>Data sources, types, volumes and storage locations are known</td><td>❌ Manual — Azure SQL databases attached</td><td>READY</td></tr><tr><td>APPMOD-DAT-02</td><td>Data quality (accuracy, completeness, consistency) is evaluated and managed with cleansing and validation</td><td>❌ Manual</td><td>READY</td></tr><tr><td>APPMOD-DAT-03</td><td>Data governance policies cover data security, privacy and compliance</td><td>❌ Manual</td><td>READY</td></tr><tr><td>APPMOD-DAT-04</td><td>A modern data infrastructure with data lakes and warehouses makes structured and unstructured data available at scale</td><td>❌ Manual — Azure Synapse workspaces attached</td><td>READY</td></tr><tr><td>APPMOD-DAT-05</td><td>Real-time data processing is available where applications and models need timely data</td><td>❌ Manual — Azure Stream Analytics jobs attached</td><td>READY</td></tr><tr><td>APPMOD-DAT-06</td><td>Data can be integrated across systems and platforms</td><td>❌ Manual — Azure Data Factory instances attached</td><td>READY</td></tr><tr><td>APPMOD-DAT-07</td><td>The data migration plan includes cleansing, transformation and validation, and a target on modern platforms such as Azure SQL Database or PostgreSQL flexible server</td><td>❌ Manual — Azure SQL servers attached</td><td>READY, INVN</td></tr><tr><td>APPMOD-DAT-08</td><td>SQL servers do not allow public network access</td><td>✅ SQL server <code>publicNetworkAccess</code></td><td>READY, LAUNCH</td></tr><tr><td>APPMOD-DAT-09</td><td>Microsoft Defender for SQL is enabled at the Standard tier</td><td>✅ Defender for SQL pricing tier</td><td>READY</td></tr></tbody></table><h3 id="application-estate-readiness-appmod-app-—-8-items" tabindex="-1">Application estate readiness (APPMOD-APP) — 8 items <a class="header-anchor" href="#application-estate-readiness-appmod-app-—-8-items" aria-label="Permalink to &quot;Application estate readiness (APPMOD-APP) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>APPMOD-APP-01</td><td>Application health is measured (response times, error rates, resource use), and under-performing applications are identified</td><td>❌ Manual — Application Insights components attached</td><td>READY</td></tr><tr><td>APPMOD-APP-02</td><td>Each application&#39;s technology stack (languages, frameworks, databases) is reviewed for compatibility with modern platforms</td><td>❌ Manual — Azure virtual machines attached</td><td>READY</td></tr><tr><td>APPMOD-APP-03</td><td>Licensing agreements and support contracts for existing applications are reviewed</td><td>❌ Manual — Azure virtual machines attached</td><td>READY</td></tr><tr><td>APPMOD-APP-04</td><td>Applications are prioritized for modernization by business value and effort, for example with an Eisenhower matrix, with stakeholder pain points gathered</td><td>❌ Manual</td><td>READY</td></tr><tr><td>APPMOD-APP-05</td><td>A modernization strategy (rehost, replatform, refactor, rebuild, retire or retain) is chosen and evaluated for each application</td><td>❌ Manual</td><td>PLAN6</td></tr><tr><td>APPMOD-APP-06</td><td>Applications move to PaaS or container platforms (App Service, Functions, AKS) where that improves scalability and management</td><td>❌ Manual — App Service web apps attached</td><td>MAT, PLAN6</td></tr><tr><td>APPMOD-APP-07</td><td>App Service web apps accept HTTPS only</td><td>✅ App Service <code>httpsOnly</code></td><td>LAUNCH</td></tr><tr><td>APPMOD-APP-08</td><td>App Service web apps require TLS 1.2 or later</td><td>✅ App Service <code>minTlsVersion</code></td><td>LAUNCH</td></tr></tbody></table><h3 id="ai-readiness-appmod-air-—-7-items" tabindex="-1">AI readiness (APPMOD-AIR) — 7 items <a class="header-anchor" href="#ai-readiness-appmod-air-—-7-items" aria-label="Permalink to &quot;AI readiness (APPMOD-AIR) — 7 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>APPMOD-AIR-01</td><td>A responsible AI approach (transparency, accountability, fairness) is defined, with governance and oversight to mitigate bias</td><td>❌ Manual</td><td>READY</td></tr><tr><td>APPMOD-AIR-02</td><td>The choice between model training and retrieval-augmented generation (RAG) is made for each use case</td><td>❌ Manual — Azure AI Search services attached</td><td>READY</td></tr><tr><td>APPMOD-AIR-03</td><td>Machine learning operations (MLOps) streamline deployment, monitoring and management of AI models</td><td>❌ Manual — Azure Machine Learning workspaces attached</td><td>READY</td></tr><tr><td>APPMOD-AIR-04</td><td>Model versioning tracks changes and supports reproducibility and compliance</td><td>❌ Manual</td><td>READY</td></tr><tr><td>APPMOD-AIR-05</td><td>Data used with AI is protected with encryption, access controls and continuous monitoring</td><td>❌ Manual — Azure AI services accounts attached</td><td>READY</td></tr><tr><td>APPMOD-AIR-06</td><td>An API management solution exposes data and services securely to approved applications</td><td>✅ API Management instances</td><td>READY</td></tr><tr><td>APPMOD-AIR-07</td><td>Data drift is monitored, and models are retrained and updated when it occurs</td><td>❌ Manual</td><td>READY</td></tr></tbody></table><h3 id="operational-readiness-appmod-ops-—-7-items" tabindex="-1">Operational readiness (APPMOD-OPS) — 7 items <a class="header-anchor" href="#operational-readiness-appmod-ops-—-7-items" aria-label="Permalink to &quot;Operational readiness (APPMOD-OPS) — 7 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>APPMOD-OPS-01</td><td>Continuous integration, continuous delivery, automation and continuous monitoring are adopted as DevOps practice</td><td>❌ Manual</td><td>READY</td></tr><tr><td>APPMOD-OPS-02</td><td>An incident response plan documents how to handle outages, and a post-incident review leads to preventive action</td><td>❌ Manual — Azure Monitor action groups attached</td><td>READY</td></tr><tr><td>APPMOD-OPS-03</td><td>A change control board (or an equivalent process) reviews significant changes and keeps detailed change logs</td><td>❌ Manual</td><td>READY</td></tr><tr><td>APPMOD-OPS-04</td><td>Teams can experiment, learn from failure and make small continuous improvements, using Agile methods such as Scrum or Kanban</td><td>❌ Manual</td><td>READY</td></tr><tr><td>APPMOD-OPS-05</td><td>Reliability and availability practices are applied to applications and services</td><td>❌ Manual — Recovery Services vaults attached</td><td>READY</td></tr><tr><td>APPMOD-OPS-06</td><td>Security is built into development and deployment (DevSecOps)</td><td>❌ Manual</td><td>READY</td></tr><tr><td>APPMOD-OPS-07</td><td>Compliance with industry regulations and standards is ensured</td><td>❌ Manual</td><td>READY</td></tr></tbody></table><h3 id="identity-security-and-compliance-appmod-sec-—-5-items" tabindex="-1">Identity, security and compliance (APPMOD-SEC) — 5 items <a class="header-anchor" href="#identity-security-and-compliance-appmod-sec-—-5-items" aria-label="Permalink to &quot;Identity, security and compliance (APPMOD-SEC) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>APPMOD-SEC-01</td><td>Applications use single sign-on with Microsoft Entra ID as the single source of identity</td><td>❌ Manual</td><td>LAUNCH</td></tr><tr><td>APPMOD-SEC-02</td><td>Multifactor authentication and Conditional Access protect all single sign-on integrations</td><td>❌ Manual</td><td>LAUNCH</td></tr><tr><td>APPMOD-SEC-03</td><td>Hybrid identity gives users one set of credentials across on-premises and cloud resources</td><td>❌ Manual</td><td>LAUNCH</td></tr><tr><td>APPMOD-SEC-04</td><td>Azure Policy assignments enforce organizational standards</td><td>✅ Azure Policy assignments (needs an Azure Policy read)</td><td>LAUNCH</td></tr><tr><td>APPMOD-SEC-05</td><td>Entra audit logs and reports are monitored to detect anomalies</td><td>❌ Manual</td><td>LAUNCH</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Items</th><th>Automated (✅)</th><th>Manual (❌)</th></tr></thead><tbody><tr><td>Organizational maturity and skills</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Estate inventory and assessment</td><td>7</td><td>0</td><td>7</td></tr><tr><td>Infrastructure and network readiness</td><td>8</td><td>2</td><td>6</td></tr><tr><td>Process readiness</td><td>7</td><td>2</td><td>5</td></tr><tr><td>Data readiness</td><td>9</td><td>2</td><td>7</td></tr><tr><td>Application estate readiness</td><td>8</td><td>2</td><td>6</td></tr><tr><td>AI readiness</td><td>7</td><td>1</td><td>6</td></tr><tr><td>Operational readiness</td><td>7</td><td>0</td><td>7</td></tr><tr><td>Identity, security and compliance</td><td>5</td><td>1</td><td>4</td></tr><tr><td><strong>Total</strong></td><td><strong>62</strong></td><td><strong>10</strong></td><td><strong>52</strong></td></tr></tbody></table><p>Ten of the 62 items can be judged from Azure data, each only on the signal it names. Four need data that is not always collected: Azure DevOps repositories and pipelines need <code>-IncludeDevOps</code>, the policy assignment item needs the Azure Policy read, and the diagnostic coverage item needs the coverage measurement. Resources Scout found (virtual machines, SQL servers, Application Insights and so on) are attached to some questions as evidence of the Azure part of the estate only. On-premises applications, source hosts other than Azure DevOps, Microsoft Entra settings and the organizational questions are not visible to Scout and are left to the person answering.</p>',34)])])}const m=e(n,[["render",s]]);export{p as __pageData,m as default};
